            if (mimeDefault instanceof java.util.Map) {
                java.util.Map<java.lang.String, java.lang.Object> map = ((java.util.Map<java.lang.String, java.lang.Object>) (mimeDefault));
                for (java.util.Map.Entry<java.lang.String, java.lang.Object> kv : map.entrySet()) {
                    org.platformlambda.automation.services.ServiceGateway.mimeTypes.put(kv.getKey(), kv.getValue().toString());
                }
            }
        } catch (java.io.IOException e) {
            org.platformlambda.automation.services.ServiceGateway.log.error("Unable to load mime-types.yml - {}", e.getMessage());
        }
        java.lang.Object mime = config.get("mime.types");
        if (mime instanceof java.util.Map) {
            java.util.Map<java.lang.String, java.lang.Object> map = ((java.util.Map<java.lang.String, java.lang.Object>) (mime));
            for (java.util.Map.Entry<java.lang.String, java.lang.Object> kv : map.entrySet()) {
                org.platformlambda.automation.services.ServiceGateway.mimeTypes.put(kv.getKey().toLowerCase(), kv.getValue().toString().toLowerCase());
            }
        }
        if (!org.platformlambda.automation.services.ServiceGateway.mimeTypes.isEmpty()) {
            org.platformlambda.automation.services.ServiceGateway.log.info("Loaded {} mime types", org.platformlambda.automation.services.ServiceGateway.mimeTypes.size());
        }
        // register authentication handler
        try {
            platform.registerPrivate(org.platformlambda.automation.services.ServiceGateway.AUTH_HANDLER, new org.platformlambda.automation.services.AuthInterceptor(), 200);
        } catch (java.io.IOException e) {
            org.platformlambda.automation.services.ServiceGateway.log.error("Unable to load {} - {}", org.platformlambda.automation.services.ServiceGateway.AUTH_HANDLER, e.getMessage());
        }
    }
}

