            org.platformlambda.automation.config.RoutingEntry.log.error("Static content filter ignored: '{} -> {}' - invalid service name", path, service);
            return null;
        }
        java.util.List<java.lang.String> pathList = new java.util.ArrayList<>();
        java.util.List<java.lang.String> exclusionList = new java.util.ArrayList<>();
        java.util.List<java.lang.Object> pList = ((java.util.List<java.lang.Object>) (path));
        for (int i = 0; i < pList.size(); i++) {
            pathList.add(config.getProperty(("static-content.filter.path[" + i) + "]"));
        }
        if (pathList.isEmpty()) {
            org.platformlambda.automation.config.RoutingEntry.log.error("static-content.filter.path is empty");
            return null;
        }
        if (exclusion instanceof java.util.List) {
            java.util.List<java.lang.Object> eList = ((java.util.List<java.lang.Object>) (exclusion));
            for (int i = 0; i < eList.size(); i++) {
                exclusionList.add(config.getProperty(("static-content.filter.exclusion[" + i) + "]"));
            }
        }
        if (invalidFilterParameters(pathList)) {
            org.platformlambda.automation.config.RoutingEntry.log.error("static-content.filter.path ignored - invalid syntax {}", path);
            return null;
        }
        if (invalidFilterParameters(exclusionList)) {
            org.platformlambda.automation.config.RoutingEntry.log.error("static-content.filter.exclusion ignored - invalid syntax {}", exclusion);
            return null;
        }
        org.platformlambda.automation.config.RoutingEntry.log.info("static-content.filter loaded: {} -> {}, exclusion {}", pathList, service, exclusionList);
        return new org.platformlambda.automation.models.SimpleHttpFilter(pathList, exclusionList, service);
    } else {
        org.platformlambda.automation.config.RoutingEntry.log.error("static-content.filter ignored - please check syntax");
    }
    return null;
}

