        if (corsList instanceof java.util.List) {
            java.util.List<java.lang.Object> list = ((java.util.List<java.lang.Object>) (corsList));
            if (isListOfMap(((java.util.List<java.lang.Object>) (corsList)))) {
                loadCors(config, list.size());
                valid = true;
            }
        }
        if (!valid) {
            org.platformlambda.automation.config.RoutingEntry.log.error("'cors' section must be a list of Access-Control entries (id, options and headers)");
        }
