    if (config.exists(org.platformlambda.automation.config.RoutingEntry.REST)) {
        java.lang.Object rest = config.get(org.platformlambda.automation.config.RoutingEntry.REST);
        boolean valid = false;
        if (rest instanceof java.util.List) {
            java.util.List<java.lang.Object> restList = ((java.util.List<java.lang.Object>) (rest));
            if (isListOfMap(restList)) {
                loadRest(config, restList.size());
                valid = true;
            }
        }
        if (!valid) {
            org.platformlambda.automation.config.RoutingEntry.log.error("'rest' section must be a list of endpoint entries (url, service, methods, timeout...)");
        }
        java.util.List<java.lang.String> exact = new java.util.ArrayList<>();
        for (java.lang.String r : org.platformlambda.automation.config.RoutingEntry.exactRoutes.keySet()) {
            if (!exact.contains(r)) {
                exact.add(r);
            }
        }
        if (exact.size() > 1) {
            java.util.Collections.sort(exact);
        }
        if (!exact.isEmpty()) {
            org.platformlambda.automation.config.RoutingEntry.log.info("Exact API path{} {}", exact.size() == 1 ? "" : "s", exact);
        }
        // sort URLs for easy parsing
        if (!org.platformlambda.automation.config.RoutingEntry.routes.isEmpty()) {
            for (java.lang.String r : org.platformlambda.automation.config.RoutingEntry.routes.keySet()) {
                int colon = r.indexOf(':');
                if (colon > 0) {
                    java.lang.String urlOnly = r.substring(colon + 1);
                    if ((!org.platformlambda.automation.config.RoutingEntry.exactRoutes.containsKey(urlOnly)) && (!org.platformlambda.automation.config.RoutingEntry.urlPaths.contains(urlOnly))) {
                        org.platformlambda.automation.config.RoutingEntry.urlPaths.add(urlOnly);
                    }
                }
            }
        }
        if (org.platformlambda.automation.config.RoutingEntry.urlPaths.size() > 1) {
            java.util.Collections.sort(org.platformlambda.automation.config.RoutingEntry.urlPaths);
        }
        if (!org.platformlambda.automation.config.RoutingEntry.urlPaths.isEmpty()) {
            org.platformlambda.automation.config.RoutingEntry.log.info("Wildcard API path{} {}", org.platformlambda.automation.config.RoutingEntry.urlPaths.size() == 1 ? "" : "s", org.platformlambda.automation.config.RoutingEntry.urlPaths);
        }
    }
}

