{
    org.platformlambda.core.util.Utility util = org.platformlambda.core.util.Utility.getInstance();
    org.platformlambda.automation.models.RouteInfo info = new org.platformlambda.automation.models.RouteInfo();
    java.lang.Object services = config.get((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.SERVICE);
    java.util.List<java.lang.String> methods = ((java.util.List<java.lang.String>) (config.get((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.METHODS)));
    java.lang.String url = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.URL_LABEL).toLowerCase();
    java.lang.String flowId = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.FLOW);
    if ((flowId != null) && (!flowId.isEmpty())) {
        info.flowId = flowId;
    }
    try {
        info.services = validateServiceList(services);
    } catch (java.lang.IllegalArgumentException e) {
        org.platformlambda.automation.config.RoutingEntry.log.error("Skipping entry {} - {}", config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"), e.getMessage());
        return;
    }
    info.primary = info.services.get(0);
    java.lang.String upload = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.UPLOAD);
    if (upload != null) {
        info.upload = "true".equalsIgnoreCase(upload);
    }
    java.lang.Object authConfig = config.get((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.AUTHENTICATION);
    // authentication: "v1.api.auth"
    if (authConfig instanceof java.lang.String) {
        java.lang.String auth = authConfig.toString().trim();
        if (util.validServiceName(auth)) {
            info.defaultAuthService = auth;
        } else {
            org.platformlambda.automation.config.RoutingEntry.log.error(org.platformlambda.automation.config.RoutingEntry.SKIP_INVALID_AUTH, config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
            return;
        }
    }
    /* authentication:
    - "x-app-name: demo : v1.demo.auth"
    - "authorization: v1.basic.auth"
    - "default: v1.api.auth"
     */
    if (authConfig instanceof java.util.List) {
        java.util.List<java.lang.Object> authList = ((java.util.List<java.lang.Object>) (authConfig));
        for (java.lang.Object o : authList) {
            java.lang.String authEntry = o.toString();
            java.util.List<java.lang.String> parts = util.split(authEntry, ": ");
            if (parts.size() == 2) {
                java.lang.String authHeader = parts.get(0);
                java.lang.String authService = parts.get(1);
                if (util.validServiceName(authService)) {
                    if (org.platformlambda.automation.config.RoutingEntry.DEFAULT_VALUE.equals(authHeader)) {
                        info.defaultAuthService = authService;
                    } else {
                        info.setAuthService(authHeader, "*", authService);
                    }
                } else {
                    org.platformlambda.automation.config.RoutingEntry.log.error(org.platformlambda.automation.config.RoutingEntry.SKIP_INVALID_AUTH, config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
                    return;
                }
            } else if (parts.size() == 3) {
                java.lang.String authHeader = parts.get(0);
                java.lang.String authValue = parts.get(1);
                java.lang.String authService = parts.get(2);
                if (util.validServiceName(authService)) {
                    info.setAuthService(authHeader, authValue, authService);
                } else {
                    org.platformlambda.automation.config.RoutingEntry.log.error(org.platformlambda.automation.config.RoutingEntry.SKIP_INVALID_AUTH, config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
                    return;
                }
            } else {
                org.platformlambda.automation.config.RoutingEntry.log.error(org.platformlambda.automation.config.RoutingEntry.SKIP_INVALID_AUTH, config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
                return;
            }
        }
        if (info.defaultAuthService == null) {
            org.platformlambda.automation.config.RoutingEntry.log.error("Skipping entry because it is missing default authentication service {}", config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
            return;
        }
    }
    java.lang.String threshold = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.THRESHOLD);
    if (threshold != null) {
        info.threshold = java.lang.Math.min(org.platformlambda.automation.config.RoutingEntry.MAX_THRESHOLD, java.lang.Math.max(org.platformlambda.automation.config.RoutingEntry.MIN_THRESHOLD, util.str2int(threshold)));
    }
    java.lang.String tracing = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.TRACING);
    if ("true".equalsIgnoreCase(tracing)) {
        info.tracing = true;
    }
    // drop query string when parsing URL
    if (url.contains("?")) {
        url = url.substring(0, url.indexOf('?'));
    }
    info.timeoutSeconds = getDurationInSeconds(config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.TIMEOUT));
    java.lang.String corsId = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.CORS);
    if (corsId != null) {
        if (org.platformlambda.automation.config.RoutingEntry.corsConfig.containsKey(corsId)) {
            info.corsId = corsId;
        } else {
            org.platformlambda.automation.config.RoutingEntry.log.error("Skipping invalid entry because cors ID {} is not found, {}", corsId, config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
            return;
        }
    }
    java.lang.String headerId = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.HEADERS);
    if (headerId != null) {
        boolean foundTransform = false;
        if (org.platformlambda.automation.config.RoutingEntry.requestHeaderInfo.containsKey(headerId)) {
            info.requestTransformId = headerId;
            foundTransform = true;
        }
        if (org.platformlambda.automation.config.RoutingEntry.responseHeaderInfo.containsKey(headerId)) {
            info.responseTransformId = headerId;
            foundTransform = true;
        }
        if (!foundTransform) {
            org.platformlambda.automation.config.RoutingEntry.log.error("Skipping invalid entry because headers ID {} is not found, {}", headerId, config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
            return;
        }
    }
    if (info.primary.startsWith(org.platformlambda.automation.config.RoutingEntry.HTTP) || info.primary.startsWith(org.platformlambda.automation.config.RoutingEntry.HTTPS)) {
        java.lang.Object rewrite = config.get((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.URL_REWRITE);
        // URL rewrite
        if (rewrite instanceof java.util.List) {
            java.util.List<java.lang.String> urlRewrite = ((java.util.List<java.lang.String>) (rewrite));
            if (urlRewrite.size() == 2) {
                info.urlRewrite = urlRewrite;
            } else {
                org.platformlambda.automation.config.RoutingEntry.log.error("Skipping entry with invalid {} - {}. It should contain a list of 2 prefixes", org.platformlambda.automation.config.RoutingEntry.URL_REWRITE, urlRewrite);
                return;
            }
        } else {
            org.platformlambda.automation.config.RoutingEntry.log.error("Skipping entry with invalid {} - {}, expected: List<String>, actual: {}", org.platformlambda.automation.config.RoutingEntry.URL_REWRITE, rewrite, rewrite.getClass().getSimpleName());
            return;
        }
        try {
            java.net.URI u = new java.net.URI(info.primary);
            if (!u.getPath().isEmpty()) {
                org.platformlambda.automation.config.RoutingEntry.log.error("Skipping entry with invalid service URL {} - Must not contain path", info.primary);
                return;
            }
            if (u.getQuery() != null) {
                org.platformlambda.automation.config.RoutingEntry.log.error("Skipping entry with invalid service URL {} - Must not contain query", info.primary);
                return;
            }
            java.lang.String trustAll = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.TRUST_ALL_CERT);
            if (info.primary.startsWith(org.platformlambda.automation.config.RoutingEntry.HTTPS) && "true".equalsIgnoreCase(trustAll)) {
                info.trustAllCert = true;
                org.platformlambda.automation.config.RoutingEntry.log.warn("Be careful - {}=true for {}", org.platformlambda.automation.config.RoutingEntry.TRUST_ALL_CERT, info.primary);
            }
            if (info.primary.startsWith(org.platformlambda.automation.config.RoutingEntry.HTTP) && (trustAll != null)) {
                org.platformlambda.automation.config.RoutingEntry.log.warn("{}=true for {} is not relevant - Do you meant https?", org.platformlambda.automation.config.RoutingEntry.TRUST_ALL_CERT, info.primary);
            }
            // set primary to ASYNC_HTTP_REQUEST
            info.host = info.primary;
            info.primary = org.platformlambda.automation.config.RoutingEntry.ASYNC_HTTP_REQUEST;
        } catch (java.net.URISyntaxException e) {
            org.platformlambda.automation.config.RoutingEntry.log.error("Skipping entry with invalid service URL {} - {}", info.primary, e.getMessage());
            return;
        }
    } else {
        java.lang.String trustAll = config.getProperty((((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "].") + org.platformlambda.automation.config.RoutingEntry.TRUST_ALL_CERT);
        if (trustAll != null) {
            org.platformlambda.automation.config.RoutingEntry.log.warn("{} parameter for {} is not relevant for regular service", org.platformlambda.automation.config.RoutingEntry.TRUST_ALL_CERT, info.primary);
        }
    }
    // remove OPTIONS method
    methods.remove(org.platformlambda.automation.config.RoutingEntry.OPTIONS_METHOD);
    if (validMethods(methods)) {
        java.util.List<java.lang.String> allMethods = new java.util.ArrayList<>(new java.util.HashSet<>(methods));
        java.util.Collections.sort(allMethods);
        info.methods = allMethods;
        if (exact) {
            org.platformlambda.automation.config.RoutingEntry.exactRoutes.put(url, true);
        }
        java.lang.String nUrl = getUrl(url, exact);
        if (nUrl == null) {
            org.platformlambda.automation.config.RoutingEntry.log.error("Skipping invalid entry {}", config.get(((org.platformlambda.automation.config.RoutingEntry.REST + "[") + idx) + "]"));
        } else {
            info.url = nUrl;
            allMethods.add(org.platformlambda.automation.config.RoutingEntry.OPTIONS_METHOD);
            for (java.lang.String m : allMethods) {
                java.lang.String key = (m + ":") + nUrl;
                org.platformlambda.automation.config.RoutingEntry.routes.put(key, info);
                // OPTIONS method is not traced
                if (org.platformlambda.automation.config.RoutingEntry.OPTIONS_METHOD.equals(m)) {
                    org.platformlambda.automation.config.RoutingEntry.log.info("{} {} -> {}, timeout={}s", m, nUrl, info.services, info.timeoutSeconds);
                } else if (info.defaultAuthService != null) {
